files.content:
.accordion {
	display: flex;
	flex-direction: column;
	width: 300px;
	border-radius: 6px;
	border: 1px solid hsl(240 6% 90%);
	background-color: white;
	color: hsl(240 4% 16%);
}

.accordion__item {
	overflow: hidden;
}

.accordion__item:first-child {
	border-top-left-radius: 6px;
	border-top-right-radius: 6px;
}

.accordion__item:last-child {
	border-bottom-left-radius: 6px;
	border-bottom-right-radius: 6px;
}

.accordion__item-header {
	display: flex;
}

.accordion__item-trigger {
	display: inline-flex;
	align-items: center;
	justify-content: space-between;
	width: 100%;
	padding: 14px 16px;
	border: none;
	border-top: 1px solid hsl(240 6% 90%);
	font-size: 16px;
	font-weight: 500;
	text-align: left;
	outline: none;
	cursor: pointer;
	background: none;
	transition:
		border-color 250ms,
		color 250ms;
}

.accordion__item:first-child .accordion__item-trigger {
	border-top: none;
}

.accordion__item-trigger:hover {
	background-color: hsl(240 6% 97%);
}

.accordion__item-trigger:focus-visible {
	z-index: 1;
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: -2px;
}

.accordion__item-trigger-icon {
	width: 20px;
	height: 20px;
	color: hsl(240 5% 46%);
	transition: transform 300ms cubic-bezier(0.87, 0, 0.13, 1);
}

.accordion__item-trigger[data-expanded] > .accordion__item-trigger-icon {
	transform: rotate(180deg);
}

.accordion__item-content {
	overflow: hidden;
	font-size: 14px;
	animation: slideUp 300ms cubic-bezier(0.87, 0, 0.13, 1);
}

.accordion__item-content[data-expanded] {
	animation: slideDown 300ms cubic-bezier(0.87, 0, 0.13, 1);
}

.accordion__item-content-text {
	padding: 16px;
	color: hsl(240 5% 26%);
}

@keyframes slideDown {
	from {
		height: 0;
	}
	to {
		height: var(--kb-accordion-content-height);
	}
}

@keyframes slideUp {
	from {
		height: var(--kb-accordion-content-height);
	}
	to {
		height: 0;
	}
}

[data-theme*="dark"] .accordion {
	border-color: hsl(240 5% 34%);
	background-color: hsl(240 4% 16%);
	color: hsl(0 100% 100% / 0.9);
}

[data-theme*="dark"] .accordion__item-trigger {
	border-top-color: hsl(240 5% 34%);
}

[data-theme*="dark"] .accordion__item-trigger:hover {
	background-color: hsl(240 4% 22%);
}

[data-theme*="dark"] .accordion__item-trigger-icon {
	color: hsl(240 5% 65%);
}

[data-theme*="dark"] .accordion__item-content-text {
	color: hsl(0 100% 100% / 0.9);
}

.alert-dialog__trigger {
	appearance: none;
	border: none;
	display: inline-flex;
	justify-content: center;
	align-items: center;
	height: 40px;
	width: auto;
	outline: none;
	border-radius: 6px;
	padding: 0 16px;
	background-color: hsl(200 98% 39%);
	color: white;
	font-size: 16px;
	line-height: 0;
	transition: 250ms background-color;
}

.alert-dialog__trigger:hover {
	background-color: hsl(201 96% 32%);
}

.alert-dialog__trigger:focus-visible {
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: 2px;
}

.alert-dialog__trigger:active {
	background-color: hsl(201 90% 27%);
}

.alert-dialog__overlay {
	position: fixed;
	inset: 0;
	z-index: 50;
	background-color: rgb(0 0 0 / 0.2);
	animation: overlayHide 250ms ease 100ms forwards;
}

.alert-dialog__overlay[data-expanded] {
	animation: overlayShow 250ms ease;
}

.alert-dialog__positioner {
	position: fixed;
	inset: 0;
	z-index: 50;
	display: flex;
	align-items: center;
	justify-content: center;
}

.alert-dialog__content {
	z-index: 50;
	max-width: min(calc(100vw - 16px), 500px);
	border: 1px solid hsl(240 5% 84%);
	border-radius: 6px;
	padding: 16px;
	background-color: white;
	box-shadow:
		0 10px 15px -3px rgb(0 0 0 / 0.1),
		0 4px 6px -4px rgb(0 0 0 / 0.1);
	animation: contentHide 300ms ease-in forwards;
}

.alert-dialog__content[data-expanded] {
	animation: contentShow 300ms ease-out;
}

.alert-dialog__header {
	display: flex;
	align-items: baseline;
	justify-content: space-between;
	margin-bottom: 12px;
}

.alert-dialog__close-button {
	height: 16px;
	width: 16px;
	color: hsl(240 5% 34%);
}

.alert-dialog__title {
	font-size: 20px;
	font-weight: 500;
	color: hsl(240 6% 10%);
}

.alert-dialog__description {
	font-size: 16px;
	color: hsl(240 5% 26%);
}

@keyframes overlayShow {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}

@keyframes overlayHide {
	from {
		opacity: 1;
	}
	to {
		opacity: 0;
	}
}

@keyframes contentShow {
	from {
		opacity: 0;
		transform: scale(0.96);
	}
	to {
		opacity: 1;
		transform: scale(1);
	}
}

@keyframes contentHide {
	from {
		opacity: 1;
		transform: scale(1);
	}
	to {
		opacity: 0;
		transform: scale(0.96);
	}
}

[data-theme*="dark"] .alert-dialog__trigger {
	background-color: hsl(201 96% 32%);
	color: hsla(0 100% 100% / 0.9);
}

[data-theme*="dark"] .alert-dialog__trigger:hover {
	background-color: hsl(200 98% 39%);
}

[data-theme*="dark"] .alert-dialog__trigger:active {
	background-color: hsl(199 89% 48%);
}

[data-theme*="dark"] .alert-dialog__content {
	border: 1px solid hsl(240 5% 26%);
	background-color: hsl(240 4% 16%);
	box-shadow: none;
}

[data-theme*="dark"] .alert-dialog__close-button {
	color: hsl(0 100% 100% / 0.8);
}

[data-theme*="dark"] .alert-dialog__title {
	color: hsl(0 100% 100% / 0.9);
}

[data-theme*="dark"] .alert-dialog__description {
	color: hsl(0 100% 100% / 0.7);
}

.alert {
	border-radius: 6px;
	padding: 12px 16px;
	background-color: hsl(204 100% 97%);
	color: hsl(201 96% 32%);
	font-size: 16px;
}

[data-theme*="dark"] .alert {
	background-color: hsla(202 80% 24% / 0.2);
	color: hsl(198 93% 60%);
}

import style from "./alert.module.css";

import { Alert } from "@kobalte/core/alert";

export function BasicExample() {
	return (
		<Alert class={style.alert}>Kobalte is going live soon, get ready!</Alert>
	);
}

.badge {
	display: inline-block;
	padding: 0.2em 0.6em;
	background-color: hsl(201 96% 32%);
	color: white;
	border-radius: 0.5rem;
	font-size: 0.875rem;
}

import style from "./badge.module.css";

import { Badge } from "@kobalte/core/badge";

export function BasicExample() {
	return (
		<Badge class={style.badge} textValue="5 unread messages">
			5 messages
		</Badge>
	);
}

.breadcrumbs__list {
	display: inline-flex;
	align-items: center;
}

.breadcrumbs__item {
	display: inline-flex;
	align-items: center;
}

.breadcrumbs__link {
	font-weight: 500;
	color: hsl(240 4% 16%);
}

.breadcrumbs__link[data-disabled] {
	color: hsl(240 4% 46%);
}

.breadcrumbs__link:hover {
	color: hsl(201 96% 32%);
}

.breadcrumbs__link[data-current] {
	font-weight: 400;
}

.breadcrumbs__separator {
	display: inline-block;
	margin: 0 4px;
	color: hsl(240 5% 65%);
}

[data-theme*="dark"] .breadcrumbs__link {
	color: hsl(0 100% 100% / 0.9);
}

[data-theme*="dark"] .breadcrumbs__link[data-disabled] {
	color: hsl(240 4% 46%);
}

[data-theme*="dark"] .breadcrumbs__link:hover {
	color: hsl(201 96% 32%);
}

.button {
	appearance: none;
	border: none;
	display: inline-flex;
	justify-content: center;
	align-items: center;
	height: 40px;
	width: auto;
	outline: none;
	border-radius: 6px;
	padding: 0 16px;
	background-color: hsl(200 98% 39%);
	color: white;
	font-size: 16px;
	line-height: 0;
	transition: 250ms background-color;
}

.button:hover {
	background-color: hsl(201 96% 32%);
}

.button:focus-visible {
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: 2px;
}

.button:active {
	background-color: hsl(201 90% 27%);
}

[data-theme*="dark"] .button {
	background-color: hsl(201 96% 32%);
	color: hsla(0 100% 100% / 0.9);
}

[data-theme*="dark"] .button:hover {
	background-color: hsl(200 98% 39%);
}

[data-theme*="dark"] .button:active {
	background-color: hsl(199 89% 48%);
