import style from "./button.module.css";

import { Button } from "@kobalte/core/button";

export function BasicExample() {
	return <Button class={style.button}>Click me</Button>;
}

.checkbox {
	display: inline-flex;
	align-items: center;
}

.checkbox__control {
	height: 20px;
	width: 20px;
	border-radius: 6px;
	border: 1px solid hsl(240 5% 84%);
	background-color: hsl(240 6% 90%);
}

.checkbox__input:focus-visible + .checkbox__control {
	outline: 2px solid hsl(200 98% 39%);
	outline-offset: 2px;
}

.checkbox__control[data-checked] {
	border-color: hsl(200 98% 39%);
	background-color: hsl(200 98% 39%);
	color: white;
}

.checkbox__control[data-invalid] {
	border-color: hsl(0 72% 51%);
}

.checkbox__label {
	margin-left: 6px;
	color: hsl(240 6% 10%);
	font-size: 14px;
	user-select: none;
}

.checkbox__description {
	margin-left: 6px;
	color: hsl(240 5% 26%);
	font-size: 12px;
	user-select: none;
}

.checkbox__error-message {
	margin-left: 6px;
	color: hsl(0 72% 51%);
	font-size: 12px;
	user-select: none;
}

[data-theme*="dark"] .checkbox__control {
	border-color: hsl(240 5% 34%);
	background-color: hsl(240 5% 26%);
}

[data-theme*="dark"] .checkbox__control[data-checked] {
	border-color: hsl(200 98% 39%);
	background-color: hsl(200 98% 39%);
	color: hsl(0 100% 100% / 0.9);
}

[data-theme*="dark"] .checkbox__control[data-invalid] {
	border-color: hsl(0 72% 51%);
}

[data-theme*="dark"] .checkbox__label {
	color: hsl(240 5% 84%);
}

[data-theme*="dark"] .checkbox__description {
	color: hsl(240 5% 65%);
}

import { createSignal } from "solid-js";

import { CheckIcon } from "../components";
import style from "./checkbox.module.css";

import { Checkbox } from "@kobalte/core/checkbox";

export function BasicExample() {
	return (
		<Checkbox class={style.checkbox}>
			<Checkbox.Input class={style.checkbox__input} />
			<Checkbox.Control class={style.checkbox__control}>
				<Checkbox.Indicator>
					<CheckIcon />
				</Checkbox.Indicator>
			</Checkbox.Control>
			<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
		</Checkbox>
	);
}

export function DefaultCheckedExample() {
	return (
		<Checkbox class={style.checkbox} defaultChecked>
			<Checkbox.Input class={style.checkbox__input} />
			<Checkbox.Control class={style.checkbox__control}>
				<Checkbox.Indicator>
					<CheckIcon />
				</Checkbox.Indicator>
			</Checkbox.Control>
			<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
		</Checkbox>
	);
}

export function ControlledExample() {
	const [checked, setChecked] = createSignal(false);

	return (
		<>
			<Checkbox
				class={style.checkbox}
				checked={checked()}
				onChange={setChecked}
			>
				<Checkbox.Input class={style.checkbox__input} />
				<Checkbox.Control class={style.checkbox__control}>
					<Checkbox.Indicator>
						<CheckIcon />
					</Checkbox.Indicator>
				</Checkbox.Control>
				<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
			</Checkbox>
			<p
				style={{ "font-size": "14px", "margin-top": "8px", "margin-bottom": 0 }}
			>
				You are {checked() ? "subscribed" : "unsubscribed"}.
			</p>
		</>
	);
}

export function DescriptionExample() {
	return (
		<Checkbox class={style.checkbox} style={{ "align-items": "flex-start" }}>
			<Checkbox.Input class={style.checkbox__input} />
			<Checkbox.Control class={style.checkbox__control}>
				<Checkbox.Indicator>
					<CheckIcon />
				</Checkbox.Indicator>
			</Checkbox.Control>
			<div
				style={{
					display: "flex",
					"flex-direction": "column",
					"align-items": "flex-start",
					"margin-top": "-2px",
				}}
			>
				<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
				<Checkbox.Description class={style.checkbox__description}>
					You will receive our weekly newsletter.
				</Checkbox.Description>
			</div>
		</Checkbox>
	);
}

export function ErrorMessageExample() {
	const [checked, setChecked] = createSignal(false);

	return (
		<Checkbox
			class={style.checkbox}
			style={{ "align-items": "flex-start" }}
			checked={checked()}
			onChange={setChecked}
			validationState={!checked() ? "invalid" : "valid"}
		>
			<Checkbox.Input class={style.checkbox__input} />
			<Checkbox.Control class={style.checkbox__control}>
				<Checkbox.Indicator>
					<CheckIcon />
				</Checkbox.Indicator>
			</Checkbox.Control>
			<div
				style={{
					display: "flex",
					"flex-direction": "column",
					"align-items": "flex-start",
					"margin-top": "-2px",
				}}
			>
				<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
				<Checkbox.ErrorMessage class={style["checkbox__error-message"]}>
					You must agree to our Terms and Conditions.
				</Checkbox.ErrorMessage>
			</div>
		</Checkbox>
	);
}

export function HTMLFormExample() {
	let formRef: HTMLFormElement | undefined;

	const onSubmit = (e: SubmitEvent) => {
		e.preventDefault();
		e.stopPropagation();

		const formData = new FormData(formRef);

		alert(JSON.stringify(Object.fromEntries(formData), null, 2));
	};

	return (
		<form
			ref={formRef}
			onSubmit={onSubmit}
			style={{
				display: "flex",
				"flex-direction": "column",
				"align-items": "center",
				gap: "24px",
			}}
		>
			<Checkbox class={style.checkbox} name="newsletter" value="subscribe">
				<Checkbox.Input class={style.checkbox__input} />
				<Checkbox.Control class={style.checkbox__control}>
					<Checkbox.Indicator>
						<CheckIcon />
					</Checkbox.Indicator>
				</Checkbox.Control>
				<Checkbox.Label class={style.checkbox__label}>Subscribe</Checkbox.Label>
			</Checkbox>
			<div style={{ display: "flex", gap: "8px" }}>
				<button type="reset" class="kb-button">
					Reset
				</button>
				<button type="submit" class="kb-button-primary">
					Submit
				</button>
			</div>
		</form>
	);
}

