import { ChevronDownIcon } from "../components";
import style from "./collapsible.module.css";

import { Collapsible } from "@kobalte/core/collapsible";

export function BasicExample() {
	return (
		<Collapsible class={style.collapsible}>
			<Collapsible.Trigger class={style.collapsible__trigger}>
				<span>What is Kobalte?</span>
				<ChevronDownIcon class={style["collapsible__trigger-icon"]} />
			</Collapsible.Trigger>
			<Collapsible.Content class={style.collapsible__content}>
				<p class={style["collapsible__content-text"]}>
					Kobalte is a UI toolkit for building accessible web apps and design
					systems with SolidJS. It provides a set of low-level UI components and
					primitives which can be the foundation for your design system
					implementation.
				</p>
			</Collapsible.Content>
		</Collapsible>
	);
}

.ColorAreaRoot {
	position: relative;
	display: flex;
	flex-direction: column;
	align-items: center;
	user-select: none;
	touch-action: none;
	width: 200px;
}

.ColorAreaBackground {
	position: relative;
	border-radius: 6px;
	height: 150px;
	width: 150px;
}

.ColorAreaThumb {
	display: block;
	width: 16px;
	height: 16px;
	border-radius: 9999px;
	border: 2px solid #fff;
	background: var(--kb-color-current);
}

.ColorAreaThumb:focus {
	outline: none;
}

.ColorArealLabel {
	font-size: 14px;
	font-weight: 500;
	user-select: none;
}

import { parseColor } from "@kobalte/core/colors";
import { createSignal } from "solid-js";
import style from "./color-area.module.css";

import { ColorArea } from "@kobalte/core/color-area";

export function BasicExample() {
	return (
		<ColorArea class={style.ColorAreaRoot}>
			<ColorArea.Label class={style.ColorAreaLabel}>Label</ColorArea.Label>
			<ColorArea.Background class={style.ColorAreaBackground}>
				<ColorArea.Thumb class={style.ColorAreaThumb}>
					<ColorArea.HiddenInputX />
					<ColorArea.HiddenInputY />
				</ColorArea.Thumb>
			</ColorArea.Background>
		</ColorArea>
	);
}

export function DefaultValueExample() {
	return (
		<ColorArea
			class={style.ColorAreaRoot}
			defaultValue={parseColor("rgb(2, 132, 197)")}
		>
			<ColorArea.Label class={style.ColorAreaLabel}>Label</ColorArea.Label>
			<ColorArea.Background class={style.ColorAreaBackground}>
				<ColorArea.Thumb class={style.ColorAreaThumb}>
					<ColorArea.HiddenInputX />
					<ColorArea.HiddenInputY />
				</ColorArea.Thumb>
			</ColorArea.Background>
		</ColorArea>
	);
}

export function ControlledValueExample() {
	const [value, setValue] = createSignal(parseColor("hsl(0, 100%, 50%)"));
	return (
		<>
			<ColorArea
				class={style.ColorAreaRoot}
				value={value()}
				onChange={setValue}
			>
				<ColorArea.Label class={style.ColorAreaLabel}>Label</ColorArea.Label>
				<ColorArea.Background class={style.ColorAreaBackground}>
					<ColorArea.Thumb class={style.ColorAreaThumb}>
						<ColorArea.HiddenInputX />
						<ColorArea.HiddenInputY />
					</ColorArea.Thumb>
				</ColorArea.Background>
			</ColorArea>
			<p
				style={{
					"font-size": "14px",
					"margin-top": "16px",
					"margin-bottom": 0,
				}}
			>
				Current color value: {value().toString("hsl")}
			</p>
		</>
	);
}

export function XAndYChannelExample() {
	const [value, setValue] = createSignal(parseColor("rgb(100, 149, 237)"));
	const [rChannel, gChannel, bChannel] = value().getColorChannels();
	return (
		<ColorArea
			class={style.ColorAreaRoot}
			value={value()}
			onChange={setValue}
			xChannel={gChannel}
			yChannel={bChannel}
		>
			<ColorArea.Label class={style.ColorAreaLabel}>Label</ColorArea.Label>
			<ColorArea.Background class={style.ColorAreaBackground}>
				<ColorArea.Thumb class={style.ColorAreaThumb}>
					<ColorArea.HiddenInputX />
					<ColorArea.HiddenInputY />
				</ColorArea.Thumb>
			</ColorArea.Background>
		</ColorArea>
	);
}

export function HTMLFormExample() {
	let formRef: HTMLFormElement | undefined;

	const onSubmit = (e: SubmitEvent) => {
		e.preventDefault();
		e.stopPropagation();

		const formData = new FormData(formRef);

		alert(JSON.stringify(Object.fromEntries(formData), null, 2));
	};

	return (
		<form
			ref={formRef}
			onSubmit={onSubmit}
			style={{
				display: "flex",
				"flex-direction": "column",
				"align-items": "center",
				gap: "24px",
			}}
		>
			<ColorArea
				class={style.ColorAreaRoot}
				defaultValue={parseColor("rgb(100, 149, 237)")}
