	align-items: center;
	justify-content: space-between;
	height: 32px;
	padding: 0 8px;
	position: relative;
	user-select: none;
	outline: none;
}

.select__item[data-disabled] {
	color: hsl(240 5% 65%);
	opacity: 0.5;
	pointer-events: none;
}

.select__item[data-highlighted] {
	outline: none;
	background-color: hsl(200 98% 39%);
	color: white;
}

.select__section {
	padding: 8px 0 0 8px;
	font-size: 14px;
	line-height: 32px;
	color: hsl(240 4% 46%);
}

.select__item-indicator {
	height: 20px;
	width: 20px;
	display: inline-flex;
	align-items: center;
	justify-content: center;
}

@keyframes contentShow {
	from {
		opacity: 0;
		transform: translateY(-8px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

@keyframes contentHide {
	from {
		opacity: 1;
		transform: translateY(0);
	}
	to {
		opacity: 0;
		transform: translateY(-8px);
	}
}

