	label: string;
	disabled: boolean;
}

interface Category {
	label: string;
	options: Food[];
}

const ALL_OPTIONS: Category[] = [
	{
		label: "Fruits",
		options: [
			{ value: "apple", label: "Apple", disabled: false },
			{ value: "banana", label: "Banana", disabled: false },
			{ value: "blueberry", label: "Blueberry", disabled: false },
			{ value: "grapes", label: "Grapes", disabled: true },
